import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.util.*;
import java.util.List;
import java.util.function.BooleanSupplier;
import java.util.zip.GZIPInputStream;

/** Converted legacy repository. No schematic commands, entities or tile entities are loaded. */
final class TreeLibrary {
    record State(String name,Map<String,String> properties){}
    record Placement(int tree,int x,int z,int rotation){}
    static final class Tree {
        final int id,group,sourceCell,sourceX,sourceZ,width,height,length;final String name;
        final short[] x,y,z;final int[] states;final int[] bounds;
        Tree(int id,int group,int cell,int sx,int sz,int width,int height,int length,String name,short[] x,short[] y,short[] z,int[] states){this.id=id;this.group=group;sourceCell=cell;sourceX=sx;sourceZ=sz;this.width=width;this.height=height;this.length=length;this.name=name;this.x=x;this.y=y;this.z=z;this.states=states;int minX=0,maxX=0,minZ=0,maxZ=0;for(int i=0;i<x.length;i++){minX=Math.min(minX,x[i]);maxX=Math.max(maxX,x[i]);minZ=Math.min(minZ,z[i]);maxZ=Math.max(maxZ,z[i]);}bounds=new int[]{minX,maxX,minZ,maxZ};}
        public String toString(){return name+" · "+width+"×"+height+"×"+length;}
    }
    record Catalog(String source,String sha,List<State> states,List<String> groups,List<Tree> trees,List<List<Tree>> byGroup){}
    private static class Holder {static final Catalog DATA=load();}
    static Catalog catalog(){return Holder.DATA;}
    static Catalog load(){try(InputStream resource=TreeLibrary.class.getResourceAsStream("/assets/tree-library.trees")){if(resource==null)throw new IOException("Bundled tree library is missing");byte[] encoded=resource.readAllBytes();try(DataInputStream in=new DataInputStream(new GZIPInputStream(new ByteArrayInputStream(encoded)))){if(!in.readUTF().equals("TERRATREES1"))throw new IOException("Invalid tree library");String source=in.readUTF();in.readUTF();String hash=fingerprint(encoded);int count=bounded(in.readInt(),1,4096);List<State> states=new ArrayList<>();for(int j=0;j<count;j++){String name=in.readUTF();if(!name.startsWith("minecraft:"))throw new IOException("Invalid tree block name");int props=bounded(in.readInt(),0,16);Map<String,String> p=new TreeMap<>();for(int k=0;k<props;k++)p.put(in.readUTF(),in.readUTF());states.add(new State(name,Map.copyOf(p)));}int groups=bounded(in.readInt(),1,128);List<String> names=new ArrayList<>();List<List<Tree>> grouped=new ArrayList<>();for(int j=0;j<groups;j++){names.add(in.readUTF());grouped.add(new ArrayList<>());}int trees=bounded(in.readInt(),1,1024);List<Tree> all=new ArrayList<>();for(int j=0;j<trees;j++){String name=in.readUTF();int group=bounded(in.readInt(),0,groups-1),cell=in.readInt(),sx=in.readShort(),sz=in.readShort(),width=in.readShort(),height=in.readShort(),length=in.readShort(),blocks=bounded(in.readInt(),1,500000);short[] x=new short[blocks],y=new short[blocks],z=new short[blocks];int[] palette=new int[blocks];for(int k=0;k<blocks;k++){x[k]=in.readShort();y[k]=in.readShort();z[k]=in.readShort();palette[k]=bounded(in.readUnsignedShort(),0,states.size()-1);if(y[k]<0||y[k]>=height)throw new IOException("Invalid tree voxel");}Tree t=new Tree(j,group,cell,sx,sz,width,height,length,name,x,y,z,palette);all.add(t);grouped.get(group).add(t);}return new Catalog(source,hash,List.copyOf(states),List.copyOf(names),List.copyOf(all),grouped.stream().map(List::copyOf).toList());}}catch(IOException e){throw new IllegalStateException("Could not load tree library: "+e.getMessage(),e);}}
    static String fingerprint(byte[] bytes){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));}catch(java.security.NoSuchAlgorithmException e){throw new AssertionError(e);}}
    static int bounded(int n,int min,int max)throws IOException{if(n<min||n>max)throw new IOException("Invalid tree catalog size or index");return n;}
    static Tree selected(TerrainGraph.Node node){int group=(int)node.p("group"),variant=(int)node.p("variant");Catalog c=catalog();if(group<0||group>=c.groups.size()||variant<0||variant>=c.byGroup.get(group).size())throw new IllegalArgumentException("Tree scatter: select a valid group and variant.");return c.byGroup.get(group).get(variant);}
    static int rx(int x,int z,int rotation){return switch(rotation){case 1->-z;case 2->-x;case 3->z;default->x;};}
    static int rz(int x,int z,int rotation){return switch(rotation){case 1->x;case 2->-z;case 3->-x;default->z;};}
    static int[] bounds(Tree tree,int rotation){int[] b=tree.bounds;int minX=999,maxX=-999,minZ=999,maxZ=-999;for(int x:new int[]{b[0],b[1]})for(int z:new int[]{b[2],b[3]}){int xx=rx(x,z,rotation),zz=rz(x,z,rotation);minX=Math.min(minX,xx);maxX=Math.max(maxX,xx);minZ=Math.min(minZ,zz);maxZ=Math.max(maxZ,zz);}return new int[]{minX,maxX,minZ,maxZ};}
    /** 0..1 moisture: rainfall, raised close to rivers and lakes. Cached per terrain so several tree nodes share it. */
    static float[] moistureIndex(EnvironmentMap base,int n,int size,int sea,BooleanSupplier stop){
        if(base.moisture!=null&&base.moisture.length==n*n)return base.moisture;
        float[] water=RiverBanks.waterDistance(base,n,sea,stop),m=new float[n*n];
        for(int i=0;i<n*n;i++){double near=Float.isFinite(water[i])?Math.max(0,1-water[i]*(double)size/n/160):0;m[i]=(float)EnvironmentNodes.clamp(EnvironmentMap.at(base.rain,i,.6f)*.7+near*.45,0,1);}
        base.moisture=m;return m;
    }
    /** Highest block a tree may reach; raised by large builds to the extended world height. */
    static volatile int ceiling=318;
    static EnvironmentMap scatter(TerrainGraph.Node node,EnvironmentMap base,float[] mask,int n,int size,int sea,long seed,BooleanSupplier stop){if(n!=size)throw new IllegalArgumentException("Tree scatter needs preview resolution equal to map size.");if(node.p("minY")>node.p("maxY"))throw new IllegalArgumentException("Tree scatter: minimum elevation exceeds maximum.");Tree tree=selected(node);List<Placement> placements=new ArrayList<>(base.trees);Random random=new Random(seed^((long)node.p("seed")*0x632BE59BD9B4E019L)^node.id*0x9E3779B97F4A7C15L);float[] shore=node.p("waterMargin")>0?RiverBanks.waterDistance(base,n,sea,stop):null;double treeline=node.values.getOrDefault("treeline",0.0),block=size/(double)n,moisture=node.values.getOrDefault("moisture",0.0);float[] wetness=moisture!=0?moistureIndex(base,n,size,sea,stop):null;if(treeline>0)MountainZones.fields(base,n,size);float peak=0;for(float v:base.height)peak=Math.max(peak,v);int top=Math.max(ceiling,ExtendedHeight.forPeak(peak)-65);int spacing=Math.max((int)node.p("spacing"),Math.max(tree.width,tree.length)+2),max=(int)node.p("count"),added=0;
        for(int gz=0;gz<n;gz+=spacing){EnvironmentNodes.cancel(stop);for(int gx=0;gx<n;gx+=spacing){if(added>=max||placements.size()>=8192)break;double chance=random.nextDouble();int x=gx+spacing/2+(int)Math.round((random.nextDouble()-.5)*spacing*.45),z=gz+spacing/2+(int)Math.round((random.nextDouble()-.5)*spacing*.45),rotation=node.p("rotate")>.5?random.nextInt(4):0;if(x<0||z<0||x>=n||z>=n)continue;int index=z*n+x;if(shore!=null&&shore[index]*(double)size/n<node.p("waterMargin"))continue;double density=node.p("density")*(mask==null?1:TerrainGenerator.clamp(mask[index],0,1));if(treeline>0){double wx=base.originX+x*block,wz=base.originZ+z*block,line=MountainZones.treeline(treeline,wx,wz,seed,base.zoneNorth[index]);density*=1-TerraForge.smooth(EnvironmentNodes.clamp((base.height[index]-line+110)/110,0,1));if(base.zoneSlope[index]>.75)density=0;}
if(wetness!=null)density*=EnvironmentNodes.clamp(.5+moisture*(wetness[index]-.55)*2.8,0,1);
if(chance>=density)continue;int h=Math.round(base.height[index]);if(base.material!=null&&(base.material[index]==6||base.material[index]==9))continue;if(h<node.p("minY")||h>node.p("maxY")||h<base.waterY(index,sea)||h+tree.height>top||EnvironmentNodes.slope(base.height,index,n,size)>node.p("slope"))continue;int[] b=bounds(tree,rotation);if(x+b[0]<1||x+b[1]>=n-1||z+b[2]<1||z+b[3]>=n-1)continue;boolean collision=false;
            for(Placement old:placements){Tree other=catalog().trees.get(old.tree);int[] ob=bounds(other,old.rotation);if(x+b[0]<=old.x+ob[1]&&x+b[1]>=old.x+ob[0]&&z+b[2]<=old.z+ob[3]&&z+b[3]>=old.z+ob[2]){collision=true;break;}}if(collision)continue;
            for(int i=0;i<tree.x.length;i++)if(tree.y[i]==0){int xx=x+rx(tree.x[i],tree.z[i],rotation),zz=z+rz(tree.x[i],tree.z[i],rotation),j=zz*n+xx;if(Math.abs(Math.round(base.height[j])-h)>2||base.waterY(j,sea)>Math.round(base.height[j])){collision=true;break;}}if(collision)continue;placements.add(new Placement(tree.id,x,z,rotation));added++;
        }}EnvironmentMap e=base.share(base.height);e.trees=List.copyOf(placements);return e;
    }
    static void writePlacements(DataOutput out,List<Placement> trees)throws IOException{out.writeInt(trees.size());if(!trees.isEmpty())out.writeUTF(catalog().sha);for(Placement t:trees){out.writeInt(t.tree);out.writeInt(t.x);out.writeInt(t.z);out.writeByte(t.rotation);}}
    static List<Placement> readPlacements(DataInput in,int size)throws IOException{int count=bounded(in.readInt(),0,8388608);if(count>0&&!in.readUTF().equals(catalog().sha))throw new IOException("This project needs a different tree library revision.");List<Placement> trees=new ArrayList<>();for(int j=0;j<count;j++)trees.add(new Placement(bounded(in.readInt(),0,catalog().trees.size()-1),bounded(in.readInt(),0,size-1),bounded(in.readInt(),0,size-1),bounded(in.readUnsignedByte(),0,3)));return List.copyOf(trees);}
    static State state(int encoded){int id=encoded-22,rotation=id%4;State original=catalog().states.get(id/4);if(rotation==0)return original;Map<String,String> p=new TreeMap<>();String[] sides={"north","east","south","west"};for(var entry:original.properties.entrySet()){String key=entry.getKey(),value=entry.getValue();if(key.equals("axis")&&rotation%2==1&&(value.equals("x")||value.equals("z")))value=value.equals("x")?"z":"x";if(key.equals("facing")){int index=Arrays.asList(sides).indexOf(value);if(index>=0)value=sides[(index+rotation)%4];}int side=Arrays.asList(sides).indexOf(key);if(side>=0)key=sides[(side+rotation)%4];p.put(key,value);}return new State(original.name,Map.copyOf(p));}
    static Map<String,TerraForge.Tag> stateTag(int encoded){State state=state(encoded);Map<String,TerraForge.Tag> tag=TerraForge.tags("Name",TerraForge.str(state.name));if(!state.properties.isEmpty()){Map<String,TerraForge.Tag> props=new TreeMap<>();for(var e:state.properties.entrySet())props.put(e.getKey(),TerraForge.str(e.getValue()));tag.put("Properties",TerraForge.compound(props));}return tag;}
    static final class SpatialIndex {
        final TerraForge.World world;final Map<Long,List<Placement>> chunks=new HashMap<>();
        SpatialIndex(TerraForge.World w){world=w;for(Placement p:w.environment.trees){int[] b=bounds(catalog().trees.get(p.tree),p.rotation);for(int z=Math.max(0,p.z+b[2])/16;z<=Math.min(w.size-1,p.z+b[3])/16;z++)for(int x=Math.max(0,p.x+b[0])/16;x<=Math.min(w.size-1,p.x+b[1])/16;x++)chunks.computeIfAbsent(key(x,z),k->new ArrayList<>()).add(p);}}
        static long key(int x,int z){return (long)x<<32|(z&0xffffffffL);}
        boolean covered(int x,int z){for(Placement p:chunks.getOrDefault(key(x/16,z/16),List.of())){int[] b=bounds(catalog().trees.get(p.tree),p.rotation);if(x>=p.x+b[0]&&x<=p.x+b[1]&&z>=p.z+b[2]&&z<=p.z+b[3])return true;}return false;}
        int[] overlay(int cx,int cz){if(!chunks.containsKey(key(cx,cz)))return null;int[] blocks=new int[world.buildHeight*256];for(Placement p:chunks.getOrDefault(key(cx,cz),List.of())){Tree tree=catalog().trees.get(p.tree);int base=world.h(p.x,p.z)+1;for(int i=0;i<tree.x.length;i++){int x=p.x+rx(tree.x[i],tree.z[i],p.rotation),z=p.z+rz(tree.x[i],tree.z[i],p.rotation),y=base+tree.y[i];if(x<cx*16||x>=cx*16+16||z<cz*16||z>=cz*16+16||x<0||z<0||x>=world.size||z>=world.size||y>world.buildHeight-65||y<=world.h(x,z)||y<=world.waterY(x,z))continue;int id=22+tree.states[i]*4+p.rotation;blocks[(y+64)*256+(z%16)*16+x%16]=id;if(tree.y[i]==0&&y-world.h(x,z)<=3)for(int yy=y-1;yy>world.h(x,z)&&yy>world.waterY(x,z);yy--)blocks[(yy+64)*256+(z%16)*16+x%16]=id;}}return blocks;}
        int topAt(int x,int z){int top=world.visibleY(x,z);for(Placement p:chunks.getOrDefault(key(x/16,z/16),List.of())){Tree tree=catalog().trees.get(p.tree);int base=world.h(p.x,p.z)+1;for(int i=0;i<tree.x.length;i++)if(p.x+rx(tree.x[i],tree.z[i],p.rotation)==x&&p.z+rz(tree.x[i],tree.z[i],p.rotation)==z)top=Math.max(top,Math.min(world.buildHeight-65,base+tree.y[i]));}return top;}
    }
    static TerrainGraph template(){TerrainGraph g=new TerrainGraph();var land=g.add(TerrainGraph.Type.NOISE,30,120);land.values.put("height",25.0);land.values.put("scale",2.0);var lift=g.add(TerrainGraph.Type.REMAP,260,120);lift.values.put("offset",18.0);g.connect(land.id,lift.id,0);var trees=g.add(TerrainGraph.Type.TREES,490,120);trees.values.put("variant",20.0);trees.values.put("density",.85);g.connect(lift.id,trees.id,0);var output=g.add(TerrainGraph.Type.OUTPUT,720,120);g.connect(trees.id,output.id,0);return g;}
    static Color color(State state){String name=state.name;if(name.endsWith("leaves"))return name.contains("spruce")?new Color(52,99,69):name.contains("birch")?new Color(131,165,66):new Color(72,130,58);String[] colors={"white","orange","magenta","light_blue","yellow","lime","pink","gray","light_gray","cyan","purple","blue","brown","green","red","black"};int[] rgb={0xddd9d0,0xd98229,0xb75bc1,0x69a9cf,0xd3b72a,0x76a831,0xd88ea3,0x494c50,0x9b9d96,0x288795,0x7d3cab,0x354795,0x765130,0x4c6c2c,0xa8312c,0x28282b};for(int j=0;j<colors.length;j++)if(name.equals("minecraft:"+colors[j]+"_wool")||name.equals("minecraft:"+colors[j]+"_terracotta")||name.equals("minecraft:"+colors[j]+"_stained_glass"))return new Color(rgb[j]);return name.contains("birch")?new Color(196,188,148):name.contains("glowstone")?new Color(219,192,106):new Color(103,76,48);}
    static BufferedImage thumbnail(Tree tree){int width=220,height=170;BufferedImage image=new BufferedImage(width,height,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setColor(new Color(19,29,36));g.fillRect(0,0,width,height);double scale=Math.min(180.0/(tree.width+tree.length),135.0/(tree.height+(tree.width+tree.length)*.3));Integer[] order=new Integer[tree.x.length];for(int i=0;i<order.length;i++)order[i]=i;Arrays.sort(order,Comparator.comparingInt(i->tree.x[i]+tree.z[i]+tree.y[i]));for(int i:order){int x=(int)(width/2+(tree.x[i]-tree.z[i])*scale*.75),y=(int)(height-20+(tree.x[i]+tree.z[i])*scale*.3-tree.y[i]*scale);g.setColor(color(catalog().states.get(tree.states[i])));g.fillRect(x,y,Math.max(1,(int)Math.ceil(scale*1.4)),Math.max(1,(int)Math.ceil(scale)));}g.dispose();return image;}
    static int[] canopy(TerraForge.World w,BufferedImage image){int[] top=new int[w.size*w.size];Arrays.fill(top,-65);for(Placement p:w.environment.trees){Tree tree=catalog().trees.get(p.tree);int base=w.h(p.x,p.z)+1;for(int i=0;i<tree.x.length;i++){int x=p.x+rx(tree.x[i],tree.z[i],p.rotation),z=p.z+rz(tree.x[i],tree.z[i],p.rotation),y=base+tree.y[i];if(x<0||z<0||x>=w.size||z>=w.size||y>319||y<=w.h(x,z)||y<=w.waterY(x,z))continue;int index=z*w.size+x;if(y>=top[index]){top[index]=y;if(image!=null)image.setRGB(x,z,color(catalog().states.get(tree.states[i])).getRGB());}}}return top;}
}
